package com.blog.fixtures.vi;

/** Vietnamese titles and names whose slugs are generated by folding diacritics. */
public final class ContentSlugVi {

    private ContentSlugVi() {}

    /** A title with diacritics; its generated slug is hoc-spring-boot-tu-dau. */
    public static final String TITLE_WITH_DIACRITICS = "Học Spring Boot từ đầu";

    /** A title that accompanies a supplied slug with diacritics. */
    public static final String FIRST_POST_TITLE = "Bài đầu tiên";

    /** A supplied slug typed with capitals and diacritics; normalised to gioi-thieu-blog. */
    public static final String SUPPLIED_SLUG = "Giới Thiệu Blog";

    /** A tag name with diacritics; its slug is duong-nguyen-hue. */
    public static final String TAG_NAME = "Đường Nguyễn Huệ";
}
